// Function Definition:
void Delay_us(uint32_t us)
{
    // Record the current CPU cycle count
    uint32_t startTick = DWT->CYCCNT;
    
    // Calculate how many CPU cycles are in our requested delay
    uint32_t delayTicks = us * (SystemCoreClock / 1000000);
    
    // Wait until the elapsed cycles reach our target. 
    while ((DWT->CYCCNT - startTick) < delayTicks)
    {
        // Block and wait
    }
}
